mkitem!{mkimpl!{impl < 'a , K : 'a , V : 'a > NodeRef < marker :: Mut < 'a > , K , V , marker :: LeafOrInternal > { #[doc = " Stocks up a possibly underfull node by merging with or stealing from a"] #[doc = " sibling. If successful but at the cost of shrinking the parent node,"] #[doc = " returns that shrunk parent node. Returns an `Err` if the node is"] #[doc = " an empty root."] fn fix_node_through_parent < A : Allocator + Clone > (self , alloc : A ,) -> Result < Option < NodeRef < marker :: Mut < 'a > , K , V , marker :: Internal > > , Self > { let len = self . len () ; if len >= MIN_LEN { Ok (None) } else { match self . choose_parent_kv () { Ok (Left (mut left_parent_kv)) => { if left_parent_kv . can_merge () { let parent = left_parent_kv . merge_tracking_parent (alloc) ; Ok (Some (parent)) } else { left_parent_kv . bulk_steal_left (MIN_LEN - len) ; Ok (None) } } Ok (Right (mut right_parent_kv)) => { if right_parent_kv . can_merge () { let parent = right_parent_kv . merge_tracking_parent (alloc) ; Ok (Some (parent)) } else { right_parent_kv . bulk_steal_right (MIN_LEN - len) ; Ok (None) } } Err (root) => { if len > 0 { Ok (None) } else { Err (root) } } } } } }}}
mkitem!{mkimpl!{impl < 'a , K : 'a , V : 'a > NodeRef < marker :: Mut < 'a > , K , V , marker :: LeafOrInternal > { #[doc = " Stocks up a possibly underfull node, and if that causes its parent node"] #[doc = " to shrink, stocks up the parent, recursively."] #[doc = " Returns `true` if it fixed the tree, `false` if it couldn't because the"] #[doc = " root node became empty."] #[doc = ""] #[doc = " This method does not expect ancestors to already be underfull upon entry"] #[doc = " and panics if it encounters an empty ancestor."] pub (super) fn fix_node_and_affected_ancestors < A : Allocator + Clone > (mut self , alloc : A ,) -> bool { loop { match self . fix_node_through_parent (alloc . clone ()) { Ok (Some (parent)) => self = parent . forget_type () , Ok (None) => return true , Err (_) => return false , } } } }}}
mkitem!{mkimpl!{impl < K , V > Root < K , V > { #[doc = " Removes empty levels on the top, but keeps an empty leaf if the entire tree is empty."] pub (super) fn fix_top < A : Allocator + Clone > (& mut self , alloc : A) { while self . height () > 0 && self . len () == 0 { self . pop_internal_level (alloc . clone ()) ; } } #[doc = " Stocks up or merge away any underfull nodes on the right border of the"] #[doc = " tree. The other nodes, those that are not the root nor a rightmost edge,"] #[doc = " must already have at least MIN_LEN elements."] pub (super) fn fix_right_border < A : Allocator + Clone > (& mut self , alloc : A) { self . fix_top (alloc . clone ()) ; if self . len () > 0 { self . borrow_mut () . last_kv () . fix_right_border_of_right_edge (alloc . clone ()) ; self . fix_top (alloc) ; } } #[doc = " The symmetric clone of `fix_right_border`."] pub (super) fn fix_left_border < A : Allocator + Clone > (& mut self , alloc : A) { self . fix_top (alloc . clone ()) ; if self . len () > 0 { self . borrow_mut () . first_kv () . fix_left_border_of_left_edge (alloc . clone ()) ; self . fix_top (alloc) ; } } #[doc = " Stocks up any underfull nodes on the right border of the tree."] #[doc = " The other nodes, those that are neither the root nor a rightmost edge,"] #[doc = " must be prepared to have up to MIN_LEN elements stolen."] pub (super) fn fix_right_border_of_plentiful (& mut self) { let mut cur_node = self . borrow_mut () ; while let Internal (internal) = cur_node . force () { let mut last_kv = internal . last_kv () . consider_for_balancing () ; debug_assert ! (last_kv . left_child_len () >= MIN_LEN * 2) ; let right_child_len = last_kv . right_child_len () ; if right_child_len < MIN_LEN { last_kv . bulk_steal_left (MIN_LEN - right_child_len) ; } cur_node = last_kv . into_right_child () ; } } }}}
mkitem!{mkimpl!{impl < 'a , K : 'a , V : 'a > Handle < NodeRef < marker :: Mut < 'a > , K , V , marker :: LeafOrInternal > , marker :: KV > { fn fix_left_border_of_left_edge < A : Allocator + Clone > (mut self , alloc : A) { while let Internal (internal_kv) = self . force () { self = internal_kv . fix_left_child (alloc . clone ()) . first_kv () ; debug_assert ! (self . reborrow () . into_node () . len () > MIN_LEN) ; } } fn fix_right_border_of_right_edge < A : Allocator + Clone > (mut self , alloc : A) { while let Internal (internal_kv) = self . force () { self = internal_kv . fix_right_child (alloc . clone ()) . last_kv () ; debug_assert ! (self . reborrow () . into_node () . len () > MIN_LEN) ; } } }}}
mkitem!{mkimpl!{impl < 'a , K : 'a , V : 'a > Handle < NodeRef < marker :: Mut < 'a > , K , V , marker :: Internal > , marker :: KV > { #[doc = " Stocks up the left child, assuming the right child isn't underfull, and"] #[doc = " provisions an extra element to allow merging its children in turn"] #[doc = " without becoming underfull."] #[doc = " Returns the left child."] fn fix_left_child < A : Allocator + Clone > (self , alloc : A ,) -> NodeRef < marker :: Mut < 'a > , K , V , marker :: LeafOrInternal > { let mut internal_kv = self . consider_for_balancing () ; let left_len = internal_kv . left_child_len () ; debug_assert ! (internal_kv . right_child_len () >= MIN_LEN) ; if internal_kv . can_merge () { internal_kv . merge_tracking_child (alloc) } else { let count = (MIN_LEN + 1) . saturating_sub (left_len) ; if count > 0 { internal_kv . bulk_steal_right (count) ; } internal_kv . into_left_child () } } #[doc = " Stocks up the right child, assuming the left child isn't underfull, and"] #[doc = " provisions an extra element to allow merging its children in turn"] #[doc = " without becoming underfull."] #[doc = " Returns wherever the right child ended up."] fn fix_right_child < A : Allocator + Clone > (self , alloc : A ,) -> NodeRef < marker :: Mut < 'a > , K , V , marker :: LeafOrInternal > { let mut internal_kv = self . consider_for_balancing () ; let right_len = internal_kv . right_child_len () ; debug_assert ! (internal_kv . left_child_len () >= MIN_LEN) ; if internal_kv . can_merge () { internal_kv . merge_tracking_child (alloc) } else { let count = (MIN_LEN + 1) . saturating_sub (right_len) ; if count > 0 { internal_kv . bulk_steal_left (count) ; } internal_kv . into_right_child () } } }}}